    {
      "id": 2,
      "prompt": "分析PostgreSQL数据库中orders表的月度销售趋势",
      "expected_output": "应该查询orders表数据，按月份分组统计销售金额，并展示趋势分析",
      "files": []
    },
    {
      "id": 3,
      "prompt": "创建一个预测模型来预测产品销量",
      "expected_output": "应该使用MindsDB创建预测模型，选择合适的引擎和参数进行训练",
      "files": []
    },
    {
      "id": 4,
      "prompt": "连接到Gmail并分析邮件数据",
      "expected_output": "应该连接Gmail数据源，查询邮件数据并进行分析",
      "files": []
    },
    {
      "id": 5,
      "prompt": "查询MongoDB中用户数据，找出活跃用户",
      "expected_output": "应该连接MongoDB，查询用户集合，筛选活跃用户并返回结果",
      "files": []
    },
    {
      "id": 6,
      "prompt": "创建一个技术文档知识库，用于智能问答",
      "expected_output": "应该创建RAG数据库，配置嵌入模型，导入技术文档，并创建智能Agent",
      "files": []
    },
    {
      "id": 7,
      "prompt": "根据技术文档回答设备报错0xE1怎么处理",
      "expected_output": "应该使用Agent查询知识库，检索相关文档，并生成准确的回答",
      "files": []
    },
    {
      "id": 8,
      "prompt": "将PDF文档导入到知识库中",
      "expected_output": "应该创建PDF数据源，提取文本内容，并导入到RAG知识库中",
      "files": []
    },
    {
      "id": 9,
      "prompt": "部署模型到生产环境并配置监控",
      "expected_output": "应该部署模型，配置性能监控、数据漂移检测和告警规则",
      "files": []
    },
    {
      "id": 10,
      "prompt": "创建A/B测试来比较两个模型的性能",
      "expected_output": "应该创建A/B测试配置，分配流量，监控指标并选择获胜模型",
      "files": []
    },
    {
      "id": 11,
      "prompt": "将模型训练过程记录到MLflow",
      "expected_output": "应该配置MLflow集成，记录训练参数、指标和模型版本",
      "files": []
    },
    {
      "id": 12,
      "prompt": "分析销售数据，自动发现增长趋势和异常",
      "expected_output": "应该执行自动数据探索，识别趋势模式，检测异常值，并生成洞察报告",
      "files": []
    },
    {
      "id": 13,
      "prompt": "预测下季度的销售额并生成预测报告",
      "expected_output": "应该创建时间序列预测模型，训练模型，生成预测结果和置信区间",
      "files": []
    },
    {
      "id": 14,
      "prompt": "为客户推荐可能感兴趣的产品",
      "expected_output": "应该创建推荐模型，分析用户行为，生成个性化推荐列表",
      "files": []
    },
    {
      "id": 15,
      "prompt": "检测交易数据中的异常行为",
      "expected_output": "应该创建异常检测模型，识别异常交易，并提供异常分析报告",
      "files": []
    },
    {
      "id": 16,
      "prompt": "连接到TDengine数据库获取工业设备的运行情况",
      "expected_output": "应该连接TDengine时序数据库，查询水质数据（流量、pH值、温度、压力等）和设备运行状态，返回实时运行报告",
      "files": []
    },
    {
      "id": 17,
      "prompt": "查询1号工业设备过去24小时的进水流量和温度浓度",
      "expected_output": "应该执行SQL查询，从TDengine数据库获取plant_001的水质数据，包括流量和温度值，并展示趋势",
      "files": []
    },
    {
      "id": 18,
      "prompt": "检查工业设备所有设备的运行状态，找出异常设备",
      "expected_output": "应该查询设备状态表，筛选alarm_status不为normal的设备，分析异常原因并提供维护建议",
      "files": []
    },
    {
      "id": 19,
      "prompt": "创建设备故障预测模型，提前预警工业设备设备故障",
      "expected_output": "应该使用历史设备数据创建分类模型，预测设备故障概率，并提供维护优先级建议",
      "files": []
    },
    {
      "id": 20,
      "prompt": "检测工业设备水质指标异常（温度超过500或pH值不在6-9范围内）",
      "expected_output": "应该查询水质数据，识别超标记录，标注异常类型（温度超标或pH异常），并提供处理建议",
      "files": []
    }
  ]
